```go
// sim.go
package sim

import (
    "C"
    "unsafe"
)

type SimInput struct {
    A float64
    B float64
    T int32
}

type result struct {
    json  string
    error error
}

// StartSimulation runs a batch asynchronously, returning channels for results and errors.
func StartSimulation(inputs []SimInput) (<-chan string, <-chan error) {
    results := make(chan string, 1)
    errors := make(chan error, 1)

    cInputs := (*C.SimInput)(C.malloc(C.size_t(len(inputs)) * C.sizeof_SimInput))
    defer C.free(unsafe.Pointer(cInputs))

    for i, inp := range inputs {
        ptr := (*C.SimInput)(unsafe.Pointer(uintptr(unsafe.Pointer(cInputs)) + uintptr(i)*C.sizeof_SimInput))
        ptr.a = C.double(inp.A)
        ptr.b = C.double(inp.B)
        ptr.t = C.int(inp.T)
    }

    ctx := &context{
        results: results,
        errors:  errors,
    }

    C.simulate_batch_async(
        cInputs,
        C.size_t(len(inputs)),
        (C.cb_t)(C.simulate_callback),
        unsafe.Pointer(ctx),
    )

    return results, errors
}

//export simulate_callback
func simulate_callback(json *C.char, len C.size_t, status C.int, ctx unsafe.Pointer) {
    c := (*context)(ctx)
    if status != 0 {
        c.errors <- nil // or wrap status as error
        return
    }
    goBytes := C.GoBytes(unsafe.Pointer(json), C.int(len))
    C.free(unsafe.Pointer(json))
    c.results <- string(goBytes)
}
```

